    26	  return {
    27	    ascii: sourceLines.map(line => rows[line - 1]).join('\n'), sourceLines,
    28	    rowForLine: (line: number) => rowByLine.get(line),
    29	    lineForRow: (row: number) => sourceLines[row],
    30	    /** Presentation can span a folded subtree; membership stays in raw node IDs. */
