    32	      const visible = sourceLines.filter(line => line >= rect.startLine && line <= rect.endLine);
    33	      if (!visible.length) return undefined;
    34	      return { ...rect, startLine: rowByLine.get(visible[0])! + 1, endLine: rowByLine.get(visible.at(-1)!)! + 1 };
    35	    },
    36	    /** Only exact, contiguous source regions can carry an editable selection. */
    37	    rect: (rect: MappingPocGridRect): MappingPocGridRect | undefined => {
    38	      const start = rowByLine.get(rect.startLine), end = rowByLine.get(rect.endLine);
    39	      if (start === undefined || end === undefined || end - start !== rect.endLine - rect.startLine) return undefined;
