python - <<'PY'
import json,subprocess
m=json.load(open('/tmp/candidate.json'))['diagrams'][0]['mappings']; files=list(dict.fromkeys(x['path'] for x in m));print('\n'.join(f'{i}: {p}' for i,p in enumerate(files)))
for i in range(0,len(files),7):
 with open(f'/tmp/ranges-{i//7}.txt','w') as out:
  for f in files[i:i+7]:
   lines=subprocess.check_output(['nl','-ba',f],text=True).splitlines(); selected=set()
   for x in m:
    if x['path']==f:selected.update(range(x['startLine'],x['endLine']+1))
   out.write('\n==== '+f+'\n');out.write('\n'.join(lines[n-1] for n in sorted(selected) if n<=len(lines))+'\n')
PY
wc -c /tmp/ranges-*.txt

